using TaskManagementSystem.Data.Seed;

namespace TaskManagementSystem.Extensions;

/// <summary>Groups middleware/endpoint setup so Program.cs stays readable.</summary>
public static class WebApplicationExtensions
{
    /// <summary>
    /// Development only: serves the OpenAPI document and the Swagger UI.
    /// - /openapi/v1.json → machine-readable API description (generated by Microsoft.AspNetCore.OpenApi)
    /// - /swagger         → interactive UI (Swashbuckle.AspNetCore.SwaggerUI) that reads that document
    /// Production does not expose either, so the API surface isn't advertised publicly.
    /// </summary>
    public static WebApplication UseApiDocumentation(this WebApplication app)
    {
        if (!app.Environment.IsDevelopment())
        {
            return app;
        }

        // The fallback policy requires login for every endpoint; the API description must stay
        // readable without a token (Development only), so it is explicitly anonymous.
        app.MapOpenApi().AllowAnonymous();

        app.UseSwaggerUI(options =>
        {
            options.SwaggerEndpoint("/openapi/v1.json", "Task Management System API v1");
            options.RoutePrefix = "swagger";
            options.DocumentTitle = "Task Management System API";
            options.DisplayRequestDuration();
            options.EnablePersistAuthorization(); // keep the pasted token after a page refresh
        });

        return app;
    }

    /// <summary>
    /// Runs the idempotent startup seeder (admin user). The app's root service provider has no
    /// HTTP request scope, so we create a scope manually to resolve scoped services
    /// (DbSeeder → UserManager → DbContext).
    /// </summary>
    public static async Task SeedDatabaseAsync(this WebApplication app)
    {
        await using var scope = app.Services.CreateAsyncScope();
        var seeder = scope.ServiceProvider.GetRequiredService<DbSeeder>();
        await seeder.SeedAsync();
    }
}
